SELECT c.segment, CASE WHEN c.credit_limit >= 16200 THEN 'high' WHEN c.credit_limit >= 3500 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MAX(o.discount) AS max_discount, SUM(o.shipping_fee) AS total_shipping_fee FROM orders o FULL OUTER JOIN stores s ON o.store_id = s.id JOIN customers c ON o.customer_id = c.id WHERE o.customer_id IS NULL GROUP BY c.segment, CASE WHEN c.credit_limit >= 16200 THEN 'high' WHEN c.credit_limit >= 3500 THEN 'mid' ELSE 'low' END;
